import hashlib
import itertools
import json
import math
import random
import subprocess
import sys
import time
import numpy as np
import pandas as pd
import torch
from torch import nn
from torch.utils.data import DataLoader, Dataset, WeightedRandomSampler
import matplotlib.pyplot as plt

subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-q', 'kaggle==2.2.2'])
from kaggle.api.kaggle_api_extended import KaggleApi
from kagglesdk.competitions.types.competition_api_service import ApiListTeamPublicSubmissionsRequest

SEED = 20260719
TOP_TEAMS = 100
EPISODES_PER_SUBMISSION = 5
COMPETITION = 'pokemon-tcg-ai-battle'
N_CARDS = 1268
ACE_SPEC_IDS = [10, 12, 13, 1080, 1082, 1085, 1088, 1089, 1092, 1093, 1095, 1096,
                1100, 1104, 1107, 1109, 1110, 1111, 1125, 1126, 1128, 1155, 1158,
                1159, 1165, 1167, 1169, 1247, 1249]
CARD_CAPS = np.array([0] + [60 if card_id in range(1, 9) else 4
                            for card_id in range(1, N_CARDS)], dtype=np.float32)

random.seed(SEED); np.random.seed(SEED); torch.manual_seed(SEED)
api = KaggleApi(); api.authenticate()
leaderboard = api.competition_leaderboard_view(COMPETITION, page_size=TOP_TEAMS)

REQUEST_INTERVAL_SECONDS = 1.1

def http_status(error):
    return getattr(getattr(error, 'response', None), 'status_code', None)

def call_with_retry(call, label, max_attempts=8, success_delay=0.0):
    for attempt in range(max_attempts):
        try:
            result = call()
            if success_delay:
                time.sleep(success_delay)
            return result
        except Exception as error:
            status = http_status(error)
            retriable = status is None or status in (408, 425, 429) or status >= 500
            if not retriable or attempt + 1 == max_attempts:
                raise
            headers = getattr(getattr(error, 'response', None), 'headers', {}) or {}
            retry_after = headers.get('Retry-After')
            try:
                delay = float(retry_after)
            except (TypeError, ValueError):
                delay = min(60.0, 3.0 * (2 ** attempt)) + random.random()
            print(f'{label}: HTTP {status or "unknown"}; retry '
                  f'{attempt + 1}/{max_attempts} in {delay:.1f}s')
            time.sleep(delay)

submission_ids = []
failed_team_ranks = []
with api.build_kaggle_client() as kaggle:
    client = kaggle.competitions.competition_api_client
    for rank, entry in enumerate(leaderboard[:TOP_TEAMS], 1):
        request = ApiListTeamPublicSubmissionsRequest()
        request.team_id = entry.to_dict()['teamId']
        try:
            response = call_with_retry(
                lambda: client.list_team_public_submissions(request),
                f'team {rank}',
                success_delay=REQUEST_INTERVAL_SECONDS,
            )
            submissions = response.to_dict().get('submissions', [])
            if submissions:
                submission_ids.append(submissions[0]['id'])
        except Exception as error:
            failed_team_ranks.append(rank)
            print(f'team {rank}: final failure '
                  f'({type(error).__name__}, HTTP {http_status(error) or "unknown"})')
        if rank % 20 == 0:
            print(f'teams {rank}/{TOP_TEAMS}, submissions={len(submission_ids)}')

assert not failed_team_ranks, (
    f'Failed to collect team submissions at ranks {failed_team_ranks}. '
    'Rerun after the API rate-limit window resets.'
)

episodes = {}
for index, submission_id in enumerate(submission_ids, 1):
    try:
        listed = call_with_retry(
            lambda: api.competition_list_episodes(submission_id),
            f'submission {submission_id}',
        )
    except Exception as error:
        print(f'submission {submission_id}: final failure '
              f'({type(error).__name__}, HTTP {http_status(error) or "unknown"})')
        listed = []
    for episode in listed[:EPISODES_PER_SUBMISSION]:
        data = episode.to_dict()
        if data.get('type') == 'EPISODE_TYPE_PUBLIC':
            episodes[data['id']] = data
    if index % 20 == 0:
        print(f'submissions {index}/{len(submission_ids)}, unique episodes={len(episodes)}')

replay_dir = Path('/tmp/replays')
replay_dir.mkdir(parents=True, exist_ok=True)
replays = []
for index, episode_id in enumerate(sorted(episodes), 1):
    path = replay_dir / f'episode-{episode_id}-replay.json'
    try:
        call_with_retry(
            lambda: api.competition_episode_replay(episode_id, path=str(replay_dir)),
            f'episode {episode_id}',
        )
        if path.exists():
            replay = json.loads(path.read_text(encoding='utf-8'))
            if replay.get('name') == 'cabt':
                replays.append(replay)
    except Exception as error:
        print(f'episode {episode_id}: final failure '
              f'({type(error).__name__}, HTTP {http_status(error) or "unknown"})')
    if index % 50 == 0:
        print(f'replays {index}/{len(episodes)}, valid={len(replays)}')

def deck_signature(deck):
    raw = ','.join(map(str, sorted(deck))).encode('ascii')
    return hashlib.sha256(raw).hexdigest()[:16]

records, deck_by_key = [], {}
for replay in replays:
    decks = true_decks(replay)
    if decks is None:
        continue
    for observer in (0, 1):
        target_deck = decks[1 - observer]
        key = deck_signature(target_deck)
        deck_by_key[key] = target_deck
        for milestone, counts in replay_snapshots(replay, observer):
            records.append((counts, key, milestone))

assert records, 'No training scenes were collected. Check API authentication and competition access.'
deck_keys = sorted(deck_by_key)
key_to_index = {key: index for index, key in enumerate(deck_keys)}
corpus_decks = np.asarray([deck_by_key[key] for key in deck_keys], dtype=np.int64)
target_deck_index = np.asarray([key_to_index[key] for _, key, _ in records], dtype=np.int64)
revealed_count = np.asarray([milestone for _, _, milestone in records], dtype=np.int64)
evidence = np.zeros((len(records), N_CARDS), dtype=np.float32)
for row, (counts, _, _) in enumerate(records):
    for card_id, count in counts.items():
        if 0 <= card_id < N_CARDS:
            evidence[row, card_id] = count

targets = np.zeros((len(corpus_decks), N_CARDS), dtype=np.float32)
for row, deck in enumerate(corpus_decks):
    np.add.at(targets[row], deck, 1)
card_caps = torch.from_numpy(CARD_CAPS)
ace_spec_ids = torch.tensor(ACE_SPEC_IDS, dtype=torch.long)

print(f'{len(replays):,} replays, {len(evidence):,} real snapshots, '
      f'{len(corpus_decks):,} unique complete decks')
print(pd.Series(revealed_count).value_counts().sort_index().rename('snapshots'))
"},{"cell_type":"code","execution_count":null,"metadata":{},"outputs":[],"source":"# Split by complete deck identity, never by individual snapshot.
deck_ids = np.unique(target_deck_index)
rng = np.random.default_rng(SEED)
n_val_decks = max(1, round(len(deck_ids) * 0.20))
deck_frequency = np.bincount(target_deck_index, minlength=len(deck_ids))
target_val_samples = len(target_deck_index) * 0.20
best_ids, best_error = None, float('inf')
for _ in range(1024):
    candidate = rng.choice(deck_ids, size=n_val_decks, replace=False)
    error = abs(deck_frequency[candidate].sum() - target_val_samples)
    if error < best_error:
        best_ids, best_error = candidate, error
val_decks = set(best_ids.tolist())
is_val = np.array([deck_id in val_decks for deck_id in target_deck_index])

class SnapshotDataset(Dataset):
    def __init__(self, indices):
        self.indices = np.asarray(indices)
    def __len__(self):
        return len(self.indices)
    def __getitem__(self, item):
        index = self.indices[item]
        return (
            torch.from_numpy(evidence[index]),
            torch.from_numpy(targets[target_deck_index[index]]),
        )

train_indices = np.flatnonzero(~is_val)
val_indices = np.flatnonzero(is_val)
print(f'train={len(train_indices):,}, validation={len(val_indices):,}')
print(f'held-out deck signatures={len(val_decks):,}')

# Synthetic reveals are generated only after the deck split.
def make_synthetic(deck_ids, seed):
    local_rng = random.Random(seed)
    rows = []
    for deck_id in sorted(deck_ids):
        deck = corpus_decks[deck_id].tolist()
        counts = Counter(deck)
        unique_ids = sorted(counts)
        for card_id in unique_ids:
            rows.append(((card_id,), (1,), deck_id))
        for first, second in itertools.combinations(unique_ids, 2):
            rows.append(((first, second), (1, 1), deck_id))
        for reveal_size in (4, 8, 12, 20):
            for _ in range(2):
                revealed = Counter(local_rng.sample(deck, reveal_size))
                ids = tuple(sorted(revealed))
                rows.append((ids, tuple(revealed[i] for i in ids), deck_id))
    return rows

class SyntheticDataset(Dataset):
    def __init__(self, rows):
        self.rows = rows
    def __len__(self):
        return len(self.rows)
    def __getitem__(self, item):
        return self.rows[item]

def collate_synthetic(rows):
    x = torch.zeros((len(rows), N_CARDS))
    y = []
    for row, (ids, counts, deck_id) in enumerate(rows):
        x[row, list(ids)] = torch.tensor(counts, dtype=torch.float32)
        y.append(torch.from_numpy(targets[deck_id]))
    return x, torch.stack(y)

train_decks = set(target_deck_index[train_indices].tolist())
synthetic_train = make_synthetic(train_decks, SEED)
synthetic_val = make_synthetic(val_decks, SEED + 1)
pattern_frequency = Counter(tuple(zip(ids, counts)) for ids, counts, _ in synthetic_train)
sample_weights = torch.tensor([
    1.0 / pattern_frequency[tuple(zip(ids, counts))]
    for ids, counts, _ in synthetic_train
])
synthetic_sampler = WeightedRandomSampler(
    sample_weights, min(20_000, len(synthetic_train)), replacement=True,
    generator=torch.Generator().manual_seed(SEED),
)
print(f'synthetic train={len(synthetic_train):,}, validation={len(synthetic_val):,}')
