The output layer allocates exactly 60 cards between hard lower and upper bounds. Revealed counts are lower bounds; ordinary cards and Special Energy are capped at four; Basic Energy is uncapped; and all ACE SPEC cards share one slot.

Training has two stages. First, singleton, pairwise, and random partial reveals from full train decks teach card co-occurrence. Then real replay snapshots fine-tune the model to the non-random way cards become public during games. Synthetic validation remains separate and uses held-out deck identities.
"},{"cell_type":"code","execution_count":null,"metadata":{},"outputs":[],"source":"class DeckBeliefNet(nn.Module):
    def __init__(self, n_cards=1268, hidden=256, caps=card_caps, ace_ids=ace_spec_ids):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(n_cards, hidden), nn.ReLU(),
            nn.Linear(hidden, hidden), nn.ReLU(),
            nn.Linear(hidden, n_cards),
        )
        self.register_buffer('caps', caps)
        self.register_buffer('ace_ids', ace_ids)
        ace_set = set(ace_ids.tolist())
        self.register_buffer('non_ace_ids', torch.tensor([
            index for index in range(n_cards) if index not in ace_set
        ]))

    @staticmethod
    def bounded_fill(logits, lower, upper, total=60.0):
        capacity = (upper - lower).clamp_min(0.0)
        target = (total - lower.sum(dim=-1, keepdim=True)).clamp_min(0.0)
        allocation = torch.zeros_like(logits)
        active = capacity > 0
        done = torch.zeros_like(target, dtype=torch.bool)
        for _ in range(logits.shape[-1]):
            masked_logits = logits.masked_fill(~active, -torch.inf)
            masked_logits = torch.where(done, torch.zeros_like(masked_logits), masked_logits)
            weights = torch.softmax(masked_logits, -1)
            remaining = (target - allocation.sum(-1, keepdim=True)).clamp_min(0.0)
            proposal = weights * remaining
            room = capacity - allocation
            saturated = active & (proposal > room + 1e-6)
            has_saturation = saturated.any(-1, keepdim=True)
            finishing = ~done & ~has_saturation
            allocation = allocation + torch.where(
                finishing, proposal, torch.where(saturated, room, torch.zeros_like(room))
            )
            done = done | finishing
            active = active & ~saturated & ~finishing
            if bool(done.all()):
                break
        return lower + allocation

    def forward(self, x):
        logits = self.net(x)
        non_logits = logits.index_select(-1, self.non_ace_ids)
        ace_logits = logits.index_select(-1, self.ace_ids)
        ace_group_logit = torch.logsumexp(ace_logits, -1, keepdim=True) - math.log(len(self.ace_ids))
        category_logits = torch.cat((non_logits, ace_group_logit), -1)
        non_lower = x.index_select(-1, self.non_ace_ids)
        ace_lower = x.index_select(-1, self.ace_ids)
        category_lower = torch.cat((non_lower, ace_lower.sum(-1, keepdim=True)), -1)
        non_caps = self.caps.expand_as(x).index_select(-1, self.non_ace_ids)
        category_caps = torch.cat((non_caps, torch.ones_like(ace_group_logit)), -1)
        categories = self.bounded_fill(category_logits, category_lower, category_caps)
        prediction = torch.zeros_like(x)
        prediction.index_copy_(-1, self.non_ace_ids, categories[..., :-1])
        extra_ace = (categories[..., -1:] - ace_lower.sum(-1, keepdim=True)).clamp_min(0.0)
        prediction.index_copy_(
            -1, self.ace_ids, ace_lower + torch.softmax(ace_logits, -1) * extra_ace
        )
        return prediction

def loss_fn(prediction, target):
    weights = 1.0 + 3.0 * (target > 0).float()
    return ((prediction - target).square() * weights).mean()

device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model = DeckBeliefNet().to(device)

def fit_stage(model, train_loader, val_loader, epochs, lr, patience, label):
    optimizer = torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=1e-4)
    best_loss, best_state, stale = float('inf'), None, 0
    history = []
    for epoch in range(epochs):
        model.train()
        for x, y in train_loader:
            x, y = x.to(device), y.to(device)
            loss = loss_fn(model(x), y)
            optimizer.zero_grad(); loss.backward(); optimizer.step()
        model.eval()
        total = 0.0
        with torch.inference_mode():
            for x, y in val_loader:
                x, y = x.to(device), y.to(device)
                total += loss_fn(model(x), y).item() * len(x)
        val_loss = total / len(val_loader.dataset)
        history.append(val_loss)
        if val_loss < best_loss - 1e-6:
            best_loss = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            stale = 0
        else:
            stale += 1
        if epoch == 0 or (epoch + 1) % 20 == 0:
            print(f'{label} epoch {epoch + 1:3d}: val_loss={val_loss:.6f}')
        if stale >= patience:
            break
    model.load_state_dict(best_state)
    return history

synthetic_history = fit_stage(
    model,
    DataLoader(
        SyntheticDataset(synthetic_train), batch_size=512,
        sampler=synthetic_sampler, collate_fn=collate_synthetic,
    ),
    DataLoader(
        SyntheticDataset(synthetic_val), batch_size=1024,
        collate_fn=collate_synthetic,
    ),
    epochs=5, lr=1e-3, patience=5, label='synthetic',
)
episode_history = fit_stage(
    model,
    DataLoader(SnapshotDataset(train_indices), batch_size=512, shuffle=True),
    DataLoader(SnapshotDataset(val_indices), batch_size=1024),
    epochs=10, lr=3e-4, patience=10, label='episode',
)
model.to('cpu').eval()
plt.plot(synthetic_history, label='synthetic validation')
plt.plot(episode_history, label='episode validation')
plt.xlabel('epoch'); plt.ylabel('validation loss'); plt.title('Leakage-safe validation')
plt.legend()
plt.show()
