class ConstantLogits(nn.Module):
    def __init__(self, logits):
        super().__init__()
        self.register_buffer('logits', logits)
    def forward(self, x):
        return self.logits.expand(len(x), -1)

mean_train_deck = torch.from_numpy(targets[target_deck_index[train_indices]].mean(axis=0))
prior_model = DeckBeliefNet()
prior_model.net = ConstantLogits(torch.log(mean_train_deck.clamp_min(1e-5)))
prior_model.eval()

metrics = []
with torch.inference_mode():
    for milestone in sorted(np.unique(revealed_count)):
        rows = val_indices[revealed_count[val_indices] == milestone]
        model_l1 = prior_l1 = model_recall = prior_recall = floor_violations = 0
        for index in rows:
            seen = torch.from_numpy(evidence[index])
            prediction = model(seen.unsqueeze(0)).squeeze(0)
            prior_prediction = prior_model(seen.unsqueeze(0)).squeeze(0)
            truth_vector = torch.from_numpy(targets[int(target_deck_index[index])])
            hidden = (truth_vector - seen).clamp_min(0)
            hidden_total = max(1.0, hidden.sum().item())
            model_hidden = (prediction - seen).clamp_min(0)
            prior_hidden = (prior_prediction - seen).clamp_min(0)
            model_l1 += torch.abs(model_hidden - hidden).sum().item() / (2 * hidden_total)
            prior_l1 += torch.abs(prior_hidden - hidden).sum().item() / (2 * hidden_total)
            model_recall += hidden[torch.topk(model_hidden, 10).indices].sum().item() / hidden_total
            prior_recall += hidden[torch.topk(prior_hidden, 10).indices].sum().item() / hidden_total
            floor_violations += int(torch.any(prediction + 1e-6 < seen))
        count = max(1, len(rows))
        metrics.append({
            'revealed cards': milestone,
            'snapshots': len(rows),
            'model unseen L1': model_l1 / count,
            'prior unseen L1': prior_l1 / count,
            'L1 reduction': 1.0 - model_l1 / prior_l1,
            'model hidden recall@10': model_recall / count,
            'prior hidden recall@10': prior_recall / count,
            'evidence-floor violations': floor_violations / count,
        })

metrics = pd.DataFrame(metrics)
display(metrics.style.format({
    'model unseen L1': '{:.3f}',
    'prior unseen L1': '{:.3f}',
    'L1 reduction': '{:.1%}',
    'model hidden recall@10': '{:.1%}',
    'prior hidden recall@10': '{:.1%}',
    'evidence-floor violations': '{:.1%}',
}))

ax = metrics.plot(x='revealed cards', y=['model unseen L1', 'prior unseen L1'], marker='o')
ax.set_ylim(0, 1); ax.set_ylabel('normalized unseen-card L1'); ax.set_title('Real held-out replay scenes')
plt.show()
