Aggregate metrics are useful, but the prediction should also make sense as a deck list. The example below comes from a real replay whose complete deck identity is held out from training. Among validation scenes with four revealed cards, we choose the scene closest to the **median model-vs-prior improvement**, rather than cherry-picking the best result.

The expected-count vector is also projected to one legal 60-card point estimate for an easy side-by-side comparison. The model is still trained and evaluated as an expected-count predictor; the integer list is only a visualization.
"},{"cell_type":"code","execution_count":null,"metadata":{},"outputs":[],"source":"import glob
from IPython.display import Markdown, display

def load_card_names():
    candidates = sorted(glob.glob('/kaggle/input/**/EN_Card_Data.csv', recursive=True))
    candidates += sorted(glob.glob('**/EN_Card_Data.csv', recursive=True))
    if not candidates:
        return {card_id: f'Card {card_id}' for card_id in range(N_CARDS)}
    cards = pd.read_csv(candidates[0])
    return {
        int(row['Card ID']): f"{row['Card Name']} [ID {int(row['Card ID'])}]"
        for _, row in cards[['Card ID', 'Card Name']].dropna().iterrows()
    }

def legal_point_deck(expected, observed):
    # Largest-remainder projection with the same per-card and ACE SPEC constraints.
    counts = torch.floor(expected + 1e-6).to(torch.int64)
    counts = torch.maximum(counts, observed.to(torch.int64))
    caps = card_caps.to(torch.int64)
    ace_ids = ace_spec_ids.to(torch.long)
    while int(counts.sum()) < 60:
        legal = counts < caps
        if int(counts.index_select(0, ace_ids).sum()) >= 1:
            legal[ace_ids] = False
        score = expected - counts.to(expected.dtype)
        score[~legal] = -torch.inf
        if not bool(torch.isfinite(score).any()):
            raise RuntimeError('Could not project the expectation to a legal 60-card deck.')
        counts[int(torch.argmax(score))] += 1
    return counts

